module top(pclk, prst_n, paddr, psel, penable, pwrite, pwdata, prdata,
     pready, adapt_enable, base_sleep_thresh, base_deep_sleep_thresh,
     active_cycles, low_freq_cycles, gated_cycles, retention_cycles,
     power_gated_cycles);
  input pclk, prst_n, psel, penable, pwrite;
  input [7:0] paddr;
  input [31:0] pwdata;
  output [31:0] prdata, active_cycles, low_freq_cycles, gated_cycles,
       retention_cycles, power_gated_cycles;
  output pready, adapt_enable;
  output [7:0] base_sleep_thresh, base_deep_sleep_thresh;
  wire pclk, prst_n, psel, penable, pwrite;
  wire [7:0] paddr;
  wire [31:0] pwdata;
  wire [31:0] prdata, active_cycles, low_freq_cycles, gated_cycles,
       retention_cycles, power_gated_cycles;
  wire pready, adapt_enable;
  wire [7:0] base_sleep_thresh, base_deep_sleep_thresh;
  csr u_csr(.pclk (pclk), .prst_n (prst_n), .paddr (8'b0), .psel
       (psel), .penable (penable), .pwrite (pwrite), .pwdata (pwdata),
       .prdata (prdata), .pready (pready), .adapt_enable
       (adapt_enable), .base_sleep_thresh (base_sleep_thresh),
       .base_deep_sleep_thresh (base_deep_sleep_thresh), .current_state
       (3'b0), .idle_count (paddr));
  statistics u_statistics(.clk (pclk), .rst_n (prst_n), .state
       (paddr[2:0]), .active_cycles (active_cycles), .low_freq_cycles
       (low_freq_cycles), .gated_cycles (gated_cycles),
       .retention_cycles (retention_cycles), .power_gated_cycles
       (power_gated_cycles));
endmodule

